// micro, then macro

const wm = new WeakMap();
const obj = {};
wm.set(obj, 'metadata');
// When obj is no longer used, entry is GC'd

const id = Symbol('id');
obj[id] = 1;
for (const k of Object.keys(obj)) {} // id not included

queueMicrotask(() => console.log('micro'));
setTimeout(() => console.log('macro'), 0);
// micro first

const p = new Proxy(obj, {
  get(t, k) { return Reflect.get(t, k); }
});

